// ── Inference (same engine as underage LGBM) ─────────────────────────────────
function lgbmPredict(vec) {
  let score = 0;
  for (const tree of LGBM_TREES) {
    let node = tree.r;
    while (node >= 0) {
      const [feat, thresh] = tree.s[node];
      const childPair = tree.c[node];
      node = vec[feat] <= thresh ? childPair[0] : childPair[1];
    }
    score += tree.l[-(node + 1)];
  }
  // Sigmoid
  return 1 / (1 + Math.exp(-score));
}

function buildVec(det) {
  const featIdx = Object.fromEntries(LGBM_FEATURES.map((f, i) => [f, i]));
  const vec = new Float32Array(LGBM_FEATURES.length);

  // bestiality__ and furry__ label scores
  for (const [sublabel, lbls] of Object.entries(det.labels || {})) {
    if (typeof lbls !== 'object') continue;
    for (const [lbl, val] of Object.entries(lbls)) {
      const key = sublabel + '__' + lbl;
      if (key in featIdx) vec[featIdx[key]] = Number(val) || 0;
    }
  }

  // Aggregate scores
  if ('_risk'  in featIdx) vec[featIdx['_risk']]  = parseFloat(det.risk  || 0) || 0;
  if ('_furry' in featIdx) vec[featIdx['_furry']] = parseFloat(det.furry || 0) || 0;

  return vec;
}

// ── Main ──────────────────────────────────────────────────────────────────────
export async function run({ inputs }) {
  const { NextNode } = DEFINITIONS;

  const LGBM_THRESHOLD = 0.75;

  const details = inputs.siglip2_details || {};
  const bestDet = details.bestiality || {};

  // Old approach: threshold on raw risk score
  const RISK_THRESHOLD = 0.06;
  const riskBlocked = parseFloat(bestDet.risk || 0) >= RISK_THRESHOLD;

  // LGBM approach
  const vec         = buildVec(bestDet);
  const lgbmScore   = lgbmPredict(vec);
  const lgbmBlocked = lgbmScore >= LGBM_THRESHOLD;

  // Top firing features
  const topFeats = LGBM_FEATURES
    .map((name, i) => ({ name, val: vec[i] }))
    .filter(f => f.val > 0.001)
    .sort((a, b) => b.val - a.val)
    .slice(0, 5)
    .map(f => `${f.name}=${f.val.toFixed(3)}`)
    .join(', ');

  return NextNode.from({
    outputs: {
      lgbm_bestiality_score:    Math.round(lgbmScore * 10000) / 10000,
      lgbm_bestiality_blocked:  lgbmBlocked,
      lgbm_bestiality_disagree: riskBlocked !== lgbmBlocked,
      lgbm_bestiality_features: topFeats,
    }
  });
}
